"""create CMSIS-style device header (<DEVICE>.h) from model.Device.

Layout follows CMSIS-Core conventions:
IRQn_Type enum -> #define core config (__NVIC_PRIO_BITS...) -> include
core_cmX.h -> peripheral register struct -> base address define.
"""

import re

from . import core_info

_ACCESS_QUALIFIER = {"rw": "__IO", "ro": "__I ", "wo": "__O "}
_SIZE_TO_CTYPE = {8: "uint8_t", 16: "uint16_t", 32: "uint32_t"}

GENERATED_BANNER = (
    "/*\n"
    " * Auto-generated by mcu-description/tools/generate.py - DO NOT EDIT BY HAND.\n"
    " * Source: mcu-description/devices/{device}.yaml\n"
    " * Regenerate: python3 mcu-description/tools/generate.py --device {device}\n"
    " */\n"
)


def _cmsis_revision(revision: str) -> int:
    """Change standard revision ``rXpY`` in YAML device to CMSIS macro 0xXXYY.

    Keeping 0x0000 for the old device declares ``unknown`` to be compatible with the old behavior, but
    rejects any other sequences seen because silently creating wrong revisions.
    """
    if revision == "unknown":
        return 0

    match = re.fullmatch(r"r(\d+)p(\d+)", revision)
    if match is None:
        raise ValueError(
            f"cpu.revision='{revision}' mismatched; Cortex-M required "
            "is rXpY (e.g. r2p0) or 'unknown'"
        )

    revision_number, patch_number = (int(part) for part in match.groups())
    if revision_number > 0xFF or patch_number > 0xFF:
        raise ValueError(
            f"cpu.revision='{revision}' pass microphone CMSIS 0xXXYY "
            "(X and Y must be male in 0..255)"
        )
    return (revision_number << 8) | patch_number


def _peripheral_struct(type_name, registers):
    lines = [f"typedef struct {{"]
    next_offset = 0
    reserved_idx = 0
    comment_column = 35
    comment_end_column = 100

    for reg in registers:
        if reg.offset > next_offset:
            gap_words = (reg.offset - next_offset) // 4
            if gap_words > 0:
                lines.append(f"  __IO uint32_t RESERVED{reserved_idx}[{gap_words}];")
                reserved_idx += 1

        qualifier = _ACCESS_QUALIFIER.get(reg.access, "__IO")
        ctype = _SIZE_TO_CTYPE.get(reg.size, "uint32_t")

        declaration = f"  {qualifier} {ctype} {reg.name};"

        if reg.description:
            comment = f"/*!< offset 0x{reg.offset:02X}, {reg.description}"
            padding = max(1, (comment_column - 1) - len(declaration))

            line = f"{declaration}{' ' * padding}{comment}"

            end_padding = max(1, (comment_end_column - 1) - len(line))
            line += f"{' ' * end_padding}*/"

            lines.append(line)
        else:
            lines.append(declaration)

        next_offset = reg.offset + reg.size // 8

    lines.append(f"}} {type_name}_TypeDef;")

    return "\n".join(lines)


def _peripheral_field_defines(type_name, registers):
    """create location macros and bitmask bits in CMSIS way."""
    lines = []
    peripheral_name = type_name.upper()

    # Share a single column of values for the entire peripheral macro. If you calculate the width
    # separately for each register, *_Pos/*_Msk blocks will be deflected when register/field names
    # have different lengths.
    macro_names = []
    for reg in registers:
        views = reg.aliases if reg.aliases else [reg]
        for view in views:
            for fld in view.fields:
                prefix = f"{peripheral_name}_{view.name.upper()}_{fld.name.upper()}"
                macro_names.extend((f"{prefix}_Pos", f"{prefix}_Msk", prefix))

    if not macro_names:
        return ""

    name_column_width = max(len(name) for name in macro_names) + 4

    for reg in registers:
        views = reg.aliases if reg.aliases else [reg]
        for view in views:
            if not view.fields:
                continue

            lines.append(f"/* Schools of {peripheral_name}_{view.name.upper()} */")
            for fld in view.fields:
                prefix = f"{peripheral_name}_{view.name.upper()}_{fld.name.upper()}"
                value_mask = (1 << fld.bit_width) - 1
                comment = f"  /*!< {fld.description} */" if fld.description else ""
                lines.append(
                    f"#define {prefix + '_Pos':<{name_column_width}}"
                    f"({fld.bit_offset}U){comment}"
                )
                lines.append(
                    f"#define {prefix + '_Msk':<{name_column_width}}"
                    f"(0x{value_mask:X}UL << {prefix}_Pos)"
                )
                lines.append(
                    f"#define {prefix:<{name_column_width}}{prefix}_Msk"
                )
            lines.append("")

    return "\n".join(lines).rstrip()


def generate(device, out_path: str):
    cpu = device.cpu
    prio_bits = cpu.extra.get("nvic_priority_bits", 2)
    vtor_present = 1 if cpu.extra.get("vtor_supported", False) else 0
    # CPU feature macros come from the GT32U2086 device description.
    mpu_present = 1 if cpu.extra.get("mpu_present", False) else 0
    fpu_present = 1 if cpu.extra.get("fpu_present", False) else 0
    # lookup() raise clear if core has not been confirmed (see core_info.py) - no silent fallback on
    # core_cm0.h as before; that earlier incorrect assumption was fixed
    # once but still remains below ".get(..., default)").
    core = core_info.lookup(cpu.core)
    cmsis_revision = _cmsis_revision(cpu.revision)
    core_header, rev_macro, needs_fpu_macro = (
        core.core_header,
        core.rev_macro,
        core.needs_fpu_macro,
    )

    lines = []
    banner = GENERATED_BANNER.format(device=device.device)
    if device.profile.flash:
        banner = banner.replace(f"--device {device.device}\n", f"--device {device.device} --profile {device.profile.name}\n")
    lines.append(banner)
    if device.description:
        lines.append("/*")
        for desc_line in device.description.strip().splitlines():
            lines.append(f" * {desc_line}")
        lines.append(" */")
    lines.append("")
    guard = f"__{device.device.upper()}_H__"
    lines.append(f"#ifndef {guard}")
    lines.append(f"#define {guard}")
    lines.append("")
    lines.append('#ifdef __cplusplus')
    lines.append('extern "C" {')
    lines.append('#endif')
    lines.append("")
    lines.append("#include <stdint.h>")
    lines.append("")

    # ---- IRQn_Type ----
    core_name = cpu.core.replace("cortex-m", "Cortex-M")
    core_irqs = [
        ("NonMaskableInt_IRQn", -14, "2 Non Maskable Interrupt"),
        ("HardFault_IRQn", -13, f"3 {core_name} Hard Fault Interrupt"),
    ]
    if core.has_extended_fault_handlers:
        core_irqs.extend([
            ("MemoryManagement_IRQn", -12, f"4 {core_name} Memory Management Interrupt"),
            ("BusFault_IRQn", -11, f"5 {core_name} Bus Fault Interrupt"),
            ("UsageFault_IRQn", -10, f"6 {core_name} Usage Fault Interrupt"),
        ])
    core_irqs.append(("SVC_IRQn", -5, f"11 {core_name} SV Call Interrupt"))
    if core.has_extended_fault_handlers:
        core_irqs.append(("DebugMonitor_IRQn", -4, f"12 {core_name} Debug Monitor Interrupt"))
    core_irqs.extend([
        ("PendSV_IRQn", -2, f"14 {core_name} Pend SV Interrupt"),
        ("SysTick_IRQn", -1, f"15 {core_name} System Tick Interrupt"),
    ])
    device_irqs = [
        (f"{irq.name}_IRQn", irq.number, " ".join(irq.description.split()))
        for irq in device.interrupts
    ]
    all_irqs = core_irqs + device_irqs
    name_width = max(26, max(len(name) for name, _, _ in all_irqs))
    value_width = max(len(f"{number},") for _, number, _ in all_irqs)
    comment_end_column = 100

    lines.append("/* =========================== Interrupt Number Definition =========================== */")
    lines.append("typedef enum")
    lines.append("{")
    for title, interrupts in [
        (f"{core_name} Processor Exceptions Numbers", core_irqs),
        (f"{device.device} device specific interrupts (mcu-description/devices/{device.device}.yaml)", device_irqs),
    ]:
        lines.append(f"  /* {title} */")
        for name, number, description in interrupts:
            declaration = f"  {name:<{name_width}} = {str(number) + ',':<{value_width}}"
            if description:
                line = f"{declaration}    /*!< {description}"
                end_padding = max(1, (comment_end_column - 1) - len(line))
                lines.append(f"{line}{' ' * end_padding}*/")
            else:
                lines.append(declaration.rstrip())
    lines.append("} IRQn_Type;")
    lines.append("")

    # ---- Core config for core_cmX.h ----
    lines.append(f"/* =========================== Core config (need before include {core_header}) ======== */")
    lines.append(f"#define {rev_macro}                0x{cmsis_revision:04X}U")
    lines.append(f"#define __MPU_PRESENT             {mpu_present}U")
    lines.append(f"#define __VTOR_PRESENT            {vtor_present}U")
    lines.append(f"#define __NVIC_PRIO_BITS          {prio_bits}U")
    lines.append("#define __Vendor_SysTickConfig    0U")
    if needs_fpu_macro:
        lines.append(f"#define __FPU_PRESENT             {fpu_present}U")
    lines.append("")
    lines.append(f"#include \"{core_header}\"          /* CMSIS-Core ARM, see arch/CortexM/CMSIS/Core */")
    lines.append(f'#include "system_{device.device}.h"')
    lines.append("")

    # ---- Peripheral structs ----
    # Instance with `type` (e.g. UART0..UART4 -> type UART) only creates a shared struct, the same way
    # Peripherals may share a register type; loader.py validates all instances of
    # the same type that have identical register layouts so takes the layout of the first instance
    # as canonical.
    lines.append("/* =========================== Peripheral register structures ======================== */")
    seen_types = set()
    for p in device.peripherals:
        if p.type in seen_types:
            continue
        seen_types.add(p.type)
        if p.description:
            lines.append("/*")
            for desc_line in p.description.strip().splitlines():
                lines.append(f" * {desc_line}")
            lines.append(" */")
        lines.append(_peripheral_struct(p.type, p.registers))
        lines.append("")

    # ---- Definition of bits of peripheral registers----
    lines.append("/* =========================== Definition of peripheral register bits ===================== */")
    seen_types = set()
    for p in device.peripherals:
        if p.type in seen_types:
            continue
        seen_types.add(p.type)
        field_defines = _peripheral_field_defines(p.type, p.registers)
        if field_defines:
            lines.append(field_defines)
            lines.append("")

    define_value_column = 25
    lines.append("/* =========================== Peripheral base address / instance ==================== */")
    for p in device.peripherals:
        define = f"#define {p.name}_BASE"
        padding = max(1, (define_value_column - 1) - len(define))
        lines.append(f"{define}{' ' * padding}0x{p.base:08X}UL")
    lines.append("")

    for p in device.peripherals:
        define = f"#define {p.name}"
        padding = max(1, (define_value_column - 1) - len(define))
        lines.append(f"{define}{' ' * padding}(({p.type}_TypeDef *) {p.name}_BASE)")
    lines.append("")

    lines.append("/* =========================== Memory map ============================================ */")
    for m in device.memory:
        define = f"#define {m.name}_BASE"
        padding = max(1, (define_value_column - 1) - len(define))
        lines.append(
            f"{define}{' ' * padding}"
            f"0x{m.address:08X}UL   /* {m.kind}, 0x{m.size:X} bytes */"
        )
    lines.append("")

    lines.append('#ifdef __cplusplus')
    lines.append('}')
    lines.append('#endif')
    lines.append("")
    lines.append(f"#endif /* {guard} */")

    with open(out_path, "w", encoding="utf-8") as f:
        f.write("\n".join(lines) + "\n")
